-- Iteración 6: consultas de sesiones por espacio y catálogos versionados de evaluación.
CREATE INDEX IF NOT EXISTS evaluation_workspace_time_idx ON learning.sesion_evaluacion(espacio_id,cuenta_id,iniciada_en DESC);
CREATE INDEX IF NOT EXISTS evaluation_execution_idx ON learning.sesion_evaluacion(ejecucion_id) WHERE ejecucion_id IS NOT NULL;

