INSERT INTO learning.heuristica_version(codigo,numero_version,locale,nombre,explicacion,pregunta,ejemplo) VALUES
('h1',1,'es-CO','Visibilidad del estado','Informe el progreso oportunamente.','¿Se reconoce qué está ocurriendo?','Una reserva anuncia que fue guardada.'),
('h2',1,'es-CO','Correspondencia con el mundo real','Use palabras familiares y orden natural.','¿El lenguaje coincide con el contexto de uso?','“Fecha de la cita” sustituye un código interno.'),
('h3',1,'es-CO','Control y libertad','Permita salir y deshacer acciones.','¿Se puede cancelar sin perder lo necesario?','Cancelar una edición conserva la reserva anterior.'),
('h4',1,'es-CO','Consistencia y estándares','Mantenga significados y convenciones.','¿La misma acción se presenta igual?','Guardar usa la misma etiqueta en dos formularios.'),
('h5',1,'es-CO','Prevención de errores','Evite problemas antes de confirmar.','¿Se detectan condiciones que producirían errores?','Una fecha pasada se rechaza antes de reservar.'),
('h6',1,'es-CO','Reconocimiento antes que recuerdo','Mantenga visibles opciones y contexto.','¿Se evita recordar información de otra pantalla?','La revisión muestra servicio, fecha y hora.'),
('h7',1,'es-CO','Flexibilidad y eficiencia','Adapte el uso a distintas experiencias.','¿Hay caminos eficientes sin excluir principiantes?','Atajos de teclado complementan botones visibles.'),
('h8',1,'es-CO','Diseño estético y minimalista','Priorice información pertinente.','¿El contenido importante destaca sin ruido?','El resumen de una cita omite publicidad ajena.'),
('h9',1,'es-CO','Reconocer, diagnosticar y recuperarse de errores','Explique problema y siguiente acción.','¿El mensaje permite corregir conservando datos?','“Seleccione una fecha futura” conserva los campos.'),
('h10',1,'es-CO','Ayuda y documentación','Ofrezca orientación contextual y localizable.','¿La ayuda explica cómo completar la tarea?','Una ayuda junto al campo explica el formato.'),
('h1',1,'en-US','Visibility of status','Provide timely progress information.','Can people recognise what is happening?','A booking announces it was saved.'),
('h2',1,'en-US','Match with the real world','Use familiar words and natural ordering.','Does language match the usage context?','“Appointment date” replaces an internal code.'),
('h3',1,'en-US','Control and freedom','Allow exits and undo actions.','Can people cancel without losing what they need?','Cancelling an edit keeps the previous booking.'),
('h4',1,'en-US','Consistency and standards','Keep meanings and conventions consistent.','Is the same action presented consistently?','Save uses the same label in two forms.'),
('h5',1,'en-US','Error prevention','Prevent problems before confirmation.','Are error-producing conditions detected?','A past date is rejected before booking.'),
('h6',1,'en-US','Recognition rather than recall','Keep choices and context visible.','Can people avoid recalling another screen’s information?','Review shows service, date and time.'),
('h7',1,'en-US','Flexibility and efficiency','Adapt use to different experience levels.','Are efficient paths available without excluding beginners?','Keyboard shortcuts complement visible buttons.'),
('h8',1,'en-US','Aesthetic and minimalist design','Prioritise relevant information.','Does important content stand out without clutter?','A booking summary omits unrelated advertising.'),
('h9',1,'en-US','Recognise, diagnose and recover from errors','Explain the problem and next action.','Can the message help correction while retaining data?','“Choose a future date” preserves the fields.'),
('h10',1,'en-US','Help and documentation','Provide findable contextual guidance.','Does help explain how to complete the task?','Help beside a field explains its format.'),
('h1',1,'pt-BR','Visibilidade do estado','Informe o progresso no momento adequado.','É possível reconhecer o que acontece?','Uma reserva anuncia que foi salva.'),
('h2',1,'pt-BR','Correspondência com o mundo real','Use palavras familiares e ordem natural.','A linguagem corresponde ao contexto?','“Data da consulta” substitui um código interno.'),
('h3',1,'pt-BR','Controle e liberdade','Permita sair e desfazer ações.','É possível cancelar sem perder o necessário?','Cancelar edição conserva a reserva anterior.'),
('h4',1,'pt-BR','Consistência e padrões','Mantenha significados e convenções.','A mesma ação se apresenta igual?','Salvar usa o mesmo rótulo em dois formulários.'),
('h5',1,'pt-BR','Prevenção de erros','Evite problemas antes de confirmar.','Condições que produziriam erros são detectadas?','Uma data passada é rejeitada antes de reservar.'),
('h6',1,'pt-BR','Reconhecimento antes da lembrança','Mantenha opções e contexto visíveis.','Evita-se lembrar informações de outra tela?','A revisão mostra serviço, data e hora.'),
('h7',1,'pt-BR','Flexibilidade e eficiência','Adapte o uso a diferentes experiências.','Há caminhos eficientes sem excluir iniciantes?','Atalhos de teclado complementam botões visíveis.'),
('h8',1,'pt-BR','Design estético e minimalista','Priorize informação pertinente.','O conteúdo importante destaca sem ruído?','O resumo de uma consulta omite publicidade alheia.'),
('h9',1,'pt-BR','Reconhecer, diagnosticar e recuperar erros','Explique problema e próxima ação.','A mensagem permite corrigir conservando dados?','“Selecione data futura” conserva os campos.'),
('h10',1,'pt-BR','Ajuda e documentação','Ofereça orientação contextual localizável.','A ajuda explica como concluir a tarefa?','Ajuda junto ao campo explica o formato.'),
('h1',1,'fr-FR','Visibilité de l’état','Informer de la progression à temps.','Reconnaît-on ce qui se passe ?','Une réservation annonce son enregistrement.'),
('h2',1,'fr-FR','Correspondance avec le monde réel','Employer des mots familiers et un ordre naturel.','Le langage correspond-il au contexte ?','« Date du rendez-vous » remplace un code interne.'),
('h3',1,'fr-FR','Contrôle et liberté','Permettre de quitter et d’annuler.','Peut-on annuler sans perdre le nécessaire ?','Annuler une modification conserve la réservation précédente.'),
('h4',1,'fr-FR','Cohérence et standards','Conserver significations et conventions.','La même action est-elle présentée pareil ?','Enregistrer a le même libellé dans deux formulaires.'),
('h5',1,'fr-FR','Prévention des erreurs','Éviter les problèmes avant confirmation.','Les conditions d’erreur sont-elles détectées ?','Une date passée est refusée avant réservation.'),
('h6',1,'fr-FR','Reconnaissance plutôt que mémorisation','Garder choix et contexte visibles.','Évite-t-on de mémoriser un autre écran ?','La révision montre service, date et heure.'),
('h7',1,'fr-FR','Flexibilité et efficacité','Adapter l’usage aux niveaux d’expérience.','Existe-t-il des chemins efficaces sans exclure les débutants ?','Les raccourcis complètent les boutons visibles.'),
('h8',1,'fr-FR','Design esthétique et minimaliste','Prioriser l’information pertinente.','Le contenu important ressort-il sans bruit ?','Le résumé d’un rendez-vous omet les publicités étrangères.'),
('h9',1,'fr-FR','Reconnaître, diagnostiquer et corriger les erreurs','Expliquer problème et prochaine action.','Le message permet-il une correction sans perte ?','« Choisissez une date future » conserve les champs.'),
('h10',1,'fr-FR','Aide et documentation','Offrir une aide contextuelle facile à trouver.','L’aide explique-t-elle comment terminer ?','Une aide près du champ explique le format.'),
('h1',1,'it-IT','Visibilità dello stato','Comunica tempestivamente l’avanzamento.','Si riconosce cosa sta succedendo?','Una prenotazione annuncia il salvataggio.'),
('h2',1,'it-IT','Corrispondenza con il mondo reale','Usa parole familiari e ordine naturale.','Il linguaggio corrisponde al contesto?','“Data dell’appuntamento” sostituisce un codice interno.'),
('h3',1,'it-IT','Controllo e libertà','Permetti uscita e annullamento.','Si può annullare senza perdere il necessario?','Annullare una modifica conserva la prenotazione precedente.'),
('h4',1,'it-IT','Coerenza e standard','Mantieni significati e convenzioni.','La stessa azione è presentata allo stesso modo?','Salva usa la stessa etichetta in due moduli.'),
('h5',1,'it-IT','Prevenzione degli errori','Evita problemi prima della conferma.','Si rilevano condizioni che causerebbero errori?','Una data passata è rifiutata prima di prenotare.'),
('h6',1,'it-IT','Riconoscimento anziché ricordo','Mantieni visibili opzioni e contesto.','Si evita di ricordare informazioni di un’altra schermata?','La revisione mostra servizio, data e ora.'),
('h7',1,'it-IT','Flessibilità ed efficienza','Adatta l’uso a esperienze diverse.','Esistono percorsi efficienti senza escludere principianti?','Scorciatoie da tastiera completano pulsanti visibili.'),
('h8',1,'it-IT','Design estetico e minimalista','Dai priorità alle informazioni pertinenti.','Il contenuto importante emerge senza rumore?','Il riepilogo di un appuntamento omette pubblicità estranea.'),
('h9',1,'it-IT','Riconoscere, diagnosticare e recuperare errori','Spiega problema e prossima azione.','Il messaggio permette di correggere mantenendo dati?','“Scegli una data futura” conserva i campi.'),
('h10',1,'it-IT','Aiuto e documentazione','Offri indicazioni contestuali reperibili.','L’aiuto spiega come completare l’attività?','Un aiuto accanto al campo spiega il formato.'),
('h1',1,'ca-ES','Visibilitat de l’estat','Informeu del progrés oportunament.','Es reconeix què està passant?','Una reserva anuncia que s’ha desat.'),
('h2',1,'ca-ES','Correspondència amb el món real','Useu paraules familiars i ordre natural.','El llenguatge coincideix amb el context?','“Data de la cita” substitueix un codi intern.'),
('h3',1,'ca-ES','Control i llibertat','Permeteu sortir i desfer accions.','Es pot cancel·lar sense perdre el necessari?','Cancel·lar una edició conserva la reserva anterior.'),
('h4',1,'ca-ES','Consistència i estàndards','Manteniu significats i convencions.','La mateixa acció es presenta igual?','Desar usa la mateixa etiqueta en dos formularis.'),
('h5',1,'ca-ES','Prevenció d’errors','Eviteu problemes abans de confirmar.','Es detecten condicions que produirien errors?','Una data passada es rebutja abans de reservar.'),
('h6',1,'ca-ES','Reconeixement abans que record','Manteniu opcions i context visibles.','S’evita recordar informació d’una altra pantalla?','La revisió mostra servei, data i hora.'),
('h7',1,'ca-ES','Flexibilitat i eficiència','Adapteu l’ús a experiències diferents.','Hi ha camins eficients sense excloure principiants?','Dreceres de teclat complementen botons visibles.'),
('h8',1,'ca-ES','Disseny estètic i minimalista','Prioritzeu informació pertinent.','El contingut important destaca sense soroll?','El resum d’una cita omet publicitat aliena.'),
('h9',1,'ca-ES','Reconèixer, diagnosticar i recuperar errors','Expliqueu problema i acció següent.','El missatge permet corregir conservant dades?','“Seleccioneu una data futura” conserva els camps.'),
('h10',1,'ca-ES','Ajuda i documentació','Oferiu orientació contextual localitzable.','L’ajuda explica com completar la tasca?','Una ajuda al costat del camp explica el format.')
ON CONFLICT(codigo,numero_version,locale) DO NOTHING;
